"""
The ways a ride can be travelled (offering or requesting a car ride, train,
bus, taxi, other) with their icons, shown on the ride cards and ride pages.
Use Ride.transport_options() to get the ones a ride has.

The icons are drawn with currentColor, so they take the colour of the text
around them (text_class on its own, or the content colour of badge_class).

The car (offer) and taxi are the same car, the taxi drawn 30 units lower in
its 470-unit square with a sign on its roof. Their viewboxes move the car
15 units down and the taxi 15 units up, so that side by side their tyres
are level and each is about as far off centre. The taxi's sign then reaches
4 units above its viewbox, so the icons are drawn with overflow visible.
On bg_class, the icon is drawn in content_class (the colour's content
colour, as on its badge), as in the search results and on the add ride page.
"""
from dataclasses import dataclass

from django.utils.safestring import mark_safe
from django.utils.translation import gettext_lazy as _


@dataclass(frozen=True)
class TransportOption:
    field: str        # BooleanField on Ride
    label: str
    text_class: str   # icon colour on its own
    badge_class: str  # badge colour, with the icon in the badge's content colour
    bg_class: str     # background colour of a box with the icon in it
    content_class: str  # icon colour in that box
    viewbox: str
    icon: str         # SVG content, to be placed in <svg viewBox="..." fill="currentColor">


